(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.016+t*0.3)*11;
  const w2x = Math.sin((x+y)*0.01+t*0.15)*8;
  const w2y = Math.cos((x-y)*0.012-t*0.2)*7;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [140+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*45, 0.075, 2.1, 1.0],
    [340+Math.cos(t*0.45)*95, 150+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*130, 110+Math.cos(t*0.42+1)*80, 0.055, 2.4, 1.1],
    [100+Math.cos(t*0.7+1)*75, 190+Math.sin(t*0.55+3)*55, 0.11, 1.6, 0.85],
    [380+Math.sin(t*0.38+4)*85, 55+Math.cos(t*0.8+2)*65, 0.065, 2.7, 1.05],
    [200+Math.cos(t*0.32+5)*110, 210+Math.sin(t*0.48)*70, 0.085, 2.0, 0.95],
    [60+Math.sin(t*0.6+3)*60, 130+Math.cos(t*0.5+4)*50, 0.1, 1.4, 1.15],
    [420+Math.cos(t*0.4+1)*50, 100+Math.sin(t*0.65+2)*60, 0.07, 2.3, 0.9]
  ];
  let aS = 0, iS = 0, tS = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.7) * w;
    tS += Math.sin(d*f*1.3 - t*sp*0.8 + 3.0) * w * 0.5;
  }
  const n = 8;
  const act = aS/n, inh = iS/n, ter = tS/n;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.7) + Math.sin(sx*0.028-sy*0.038+t*0.95))/2;
  const bg2 = Math.sin((sx+sy)*0.11+t*2.2)*0.18 + Math.sin((sx-sy)*0.09-t*1.8)*0.18;
  const bg3 = Math.sin(sx*0.06+t*1.5)*Math.sin(sy*0.055-t*1.2)*0.25;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.08-ang*2-t*2.5)*0.3;
  const spiral = (sp1+sp2)*0.35 + sp3;
  const lap = (Math.sin(sx*0.2)*Math.sin(sy*0.2) + Math.sin((sx+sy)*0.14+t*0.8)*0.4 + Math.sin((sx-sy)*0.12-t*0.6)*0.3);
  const cell = Math.tanh(lap*1.8)*0.25;
  const rd1 = act - inh*0.65 + bg*0.25 + spiral;
  const rd2 = ter*0.4 + Math.tanh((act+inh)*0.5)*0.6;
  const cross = Math.sin(rd1*Math.PI)*Math.cos(rd2*Math.PI*0.7)*0.3;
  const reaction = Math.tanh((rd1 + cross + cell)*2.0);
  const micro = Math.sin(sx*0.4+sy*0.35+t*3)*Math.sin(sx*0.3-sy*0.45-t*2.5)*0.08;
  const blend = reaction*0.7 + cell*0.2 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[10,35,85],[12,65,105],[18,110,125],
    [35,155,145],[120,190,130],[210,195,80],[230,150,65],
    [215,95,60],[185,55,75],[120,30,65],[55,18,55],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
  const lum = 0.78 + Math.sin(reaction*Math.PI)*0.22;
  const edge = Math.abs(reaction)>0.72 ? 1.18 : Math.abs(reaction)>0.5 ? 1.06 : 1.0;
  const depth = 1.0 + Math.sin(dist*0.008-t*0.3)*0.08;
  const m = lum * edge * depth;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*m)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*m)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*m)|0
  ];
}
